import mpmath as mp

def theta_ref(n, z, q, nd=0, dps=None):
    with mp.workdps((dps or mp.dps) + 30):
        S = mp.mpc(0)
        # upper tail cutoff: |q|^(k^2) < e^-dps
        import math
        lq = abs(mp.log(abs(q)))
        # k_max: k^2 * lq > dps+15  -> k > sqrt((dps+15)/lq)
        kmax = int(math.sqrt((dps or mp.dps) * 1.2 / lq)) + 5 if lq > 0 else 200
        if n == 1:
            S = 0
            for k in range(0, kmax):
                S += (-1)**k * q**(k*(k+1)) * (mp.sin((2*k+1)*z) if nd == 0
                      else _deri_sin((2*k+1)*z, nd))
            return 2 * q**mp.mpf('0.25') * S
        if n == 2:
            S = 0
            for k in range(0, kmax):
                S += q**(k*(k+1)) * (mp.cos((2*k+1)*z) if nd == 0
                      else _deri_cos((2*k+1)*z, nd))
            return 2 * q**mp.mpf('0.25') * S
        if n == 3:
            S = 1
            for k in range(1, kmax):
                S += q**(k*k) * (mp.cos(2*k*z) if nd == 0 else _deri_cos(2*k*z, nd))
            return 1 + 2*S
        if n == 4:
            S = 1
            for k in range(1, kmax):
                S += (-1)**k * q**(k*k) * (mp.cos(2*k*z) if nd == 0 else _deri_cos(2*k*z, nd))
            return 1 + 2*S
        raise ValueError(n)

def _deri_sin(w, nd):
    # d^nd/dz^nd sin(w z) = w^nd sin(wz + nd*pi/2)
    return w**nd * mp.sin(w + nd*mp.pi/2)
def _deri_cos(w, nd):
    return w**nd * mp.cos(w - nd*mp.pi/2)
